arguments.command:
python << 'EOF'
import csv
assets=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def load(path):
    rows=[r for r in csv.reader(open(path))]
    d={r[0]:r for r in rows[1:] if len(r)>=8}
    return d
for a in assets:
    d=load(f'../persistent/stock_data/{a}.csv')
    dates=sorted(k for k in d if k<='2033-08-02')
    def px(dt,idx=2):
        return float(d[dt][idx]) if dt in d else None
    c=px(dates[-1]); c5=px(dates[-6]); c20=px(dates[-21]); c60=px(dates[-61]); c120=px(dates[-121])
    def r(x): return 100*(c/x-1) if x else float('nan')
    print(f"{a:10s} last={dates[-1]} px={c:9.3f} 5d={r(c5):+6.1f}% 20d={r(c20):+7.1f}% 60d={r(c60):+7.1f}% 120d={r(c120):+8.1f}%")
EOF

python -c "
import json, glob
for f in sorted(glob.glob('factors/*.json')):
    if f.endswith('.bak'): continue
    try:
        d=json.load(open(f))
        keys=list(d.keys())[:8]
        print(f.split('/')[-1], '| keys:', keys)
        # try to dig out meta
        for k in keys:
            v=d[k]
            if isinstance(v,dict):
                print('   ', k, '->', list(v.keys())[:10])
            else:
                print('   ', k, '->', str(v)[:120])
        break_after=False
    except Exception as e:
        print(f, 'ERR', e)
"

